"""

import json
import threading
import time
from typing import Optional, Dict, Any

# ============================================================
# 1. CDP 客户端（极简版）
# ============================================================

class CdpClient:
    """通过 WebSocket 连接 Chrome CDP 的极简客户端"""

    def __init__(self, ws_url: str):
        self.ws_url = ws_url
        self.ws = None  # websocket.WebSocket 实例（同步版）
        self._message_id = 0
        self._pending: Dict[int, threading.Event] = {}
        self._responses: Dict[int, Any] = {}
        self._recv_thread: Optional[threading.Thread] = None
        self._running = False

    def connect(self):
        """建立 WebSocket 连接（同步版）"""
        import websocket

        self.ws = websocket.create_connection(
            self.ws_url,
            timeout=10,
            enable_multithread=True,
        )
        self._running = True
        # 启动后台线程接收消息
        self._recv_thread = threading.Thread(target=self._recv_loop, daemon=True)
        self._recv_thread.start()
        print("[已连接] Chrome CDP")

    def _recv_loop(self):
        """后台线程：持续接收 WebSocket 消息"""
        import websocket

        while self._running:
            try:
                message = self.ws.recv()
                if not message:
                    continue
                data = json.loads(message)
                # 检查是否是命令响应（有 id 字段）
                if "id" in data:
                    event = self._pending.pop(data["id"], None)
                    if event:
                        self._responses[data["id"]] = data
                        event.set()
                # 否则是事件推送，忽略
            except websocket.WebSocketTimeoutException:
                continue
            except Exception as e:
                if self._running:
                    print(f"[接收错误] {e}")
                break

    def send(self, method: str, params: dict = None, session_id: str = None) -> dict:
        """发送 CDP 命令并等待响应"""
        self._message_id += 1
        cmd = {
            "id": self._message_id,
            "method": method,
            "params": params or {},
        }
        if session_id:
            cmd["sessionId"] = session_id

        event = threading.Event()
        self._pending[self._message_id] = event

        # 发送命令
        self.ws.send(json.dumps(cmd))

        # 等待响应（10 秒超时）
        if not event.wait(timeout=10):
            raise TimeoutError(f"命令超时: {method}")

        response = self._responses.pop(self._message_id)

        # 检查错误
        if "error" in response:
            raise Exception(f"CDP 错误: {response['error']}")

        return response.get("result", {})

    def close(self):
        self._running = False
        if self.ws:
            try:
                self.ws.close()
            except Exception:
                pass


# ============================================================
# 2. 辅助函数：格式化输出
# ============================================================

def print_separator(title: str):
    """打印带标题的分隔线"""
    width = 70
    print("\n" + "=" * width)
    print(f"  {title}")
    print("=" * width)


def print_dom_tree(node: dict, indent: int = 0):
    """递归打印 DOM 树（简化版）"""
    prefix = "  " * indent
    node_type = node.get("nodeType")
    node_name = node.get("nodeName", "")

    if node_type == 1:  # 元素节点
        attrs = node.get("attributes", [])
        attr_str = ""
        if attrs:
            attr_pairs = []
            for i in range(0, len(attrs), 2):
                if i + 1 < len(attrs):
                    attr_pairs.append(f'{attrs[i]}="{attrs[i+1]}"')
            if attr_pairs:
                attr_str = " " + " ".join(attr_pairs)

        children = node.get("children", [])
        print(f"{prefix}<{node_name.lower()}{attr_str}>  ({len(children)} children)")

        for child in children:
            print_dom_tree(child, indent + 1)

    elif node_type == 3:  # 文本节点
        text = node.get("nodeValue", "").strip()
        if text:
            print(f'{prefix}  "{text}"')


def _extract_ax_value(value: Optional[dict]) -> str:
    """从 AXValue 对象中提取字符串值"""
    if not value:
        return ""
    val = value.get("value")
    if val is None:
        return ""
    if isinstance(val, str):
        return val
    if isinstance(val, bool):
        return str(val).lower()
    if isinstance(val, (int, float)):
        return str(val)
    return ""


def _count_dom_nodes(node: dict) -> int:
    """递归统计 DOM 节点数"""
    count = 1
    for child in node.get("children", []):
        count += _count_dom_nodes(child)
    return count


def _print_ax_tree_hierarchical(nodes: list):
    """将扁平的 AX 节点列表按树结构打印"""
    node_map = {node["nodeId"]: node for node in nodes}

    # 找到根节点（没有被任何节点引用的节点）
    all_child_ids = set()
    for node in nodes:
        for cid in node.get("childIds", []):
            all_child_ids.add(cid)

    roots = [n for n in nodes if n["nodeId"] not in all_child_ids]

    def _print(node: dict, indent: int):
        if node.get("ignored", False):
            return

        role = _extract_ax_value(node.get("role"))
        name = _extract_ax_value(node.get("name"))
        value = _extract_ax_value(node.get("value"))

        if role == "InlineTextBox":
            return

        prefix = "  " * indent
        line = f"{prefix}- {role}"
        if name:
            line += f' "{name}"'
        if value and value != name:
            line += f": {value}"

        # 属性
        props = node.get("properties", [])
        prop_strs = []
        for prop in props:
            pname = prop.get("name", "")
            pvalue = _extract_ax_value(prop.get("value"))
            if pvalue:
                prop_strs.append(f"{pname}={pvalue}")
        if prop_strs:
            line += f" [{', '.join(prop_strs)}]"

        print(line)

        for cid in node.get("childIds", []):
            if cid in node_map:
                _print(node_map[cid], indent + 1)

    for root in roots:
        _print(root, 0)


