def get_cdp_url_from_http(host: str = "localhost", port: int = 9222) -> Optional[str]:
    """通过 HTTP 端点自动获取 WebSocket URL"""
    import urllib.request

    try:
        resp = urllib.request.urlopen(f"http://{host}:{port}/json/version", timeout=3)
        data = json.loads(resp.read())
        ws_url = data.get("webSocketDebuggerUrl")
        if ws_url:
            print(f"  ✓ 自动获取到 CDP URL: {ws_url}")
            return ws_url
        else:
            print("  ✗ HTTP 响应中没有 webSocketDebuggerUrl 字段")
            return None
    except Exception as e:
        print(f"  ✗ 无法连接 Chrome 调试端口: {e}")
        return None


def find_chrome_processes():
    """尝试查找正在运行的 Chrome 进程"""
    import subprocess

    try:
        result = subprocess.run(
            ["tasklist", "/fi", "IMAGENAME eq chrome.exe", "/fo", "csv", "/nh"],
            capture_output=True, text=True, timeout=5
        )
        lines = [l.strip() for l in result.stdout.split("\n") if l.strip()]
        if lines:
            print(f"  发现 {len(lines)} 个 Chrome 进程正在运行")
            return True
        else:
            print("  未发现运行中的 Chrome 进程")
            return False
    except Exception:
        return False


