def main():
    print("=" * 70)
    print("  Accessibility Tree vs DOM 对比演示")
    print("  基于 Chrome DevTools Protocol (CDP)")
    print("=" * 70)
    print()
    print("使用说明：")
    print("  1. 先启动 Chrome 远程调试：")
    print('     chrome.exe --remote-debugging-port=9222')
    print("  2. 然后运行本脚本")
    print()

    # ---- 自动检测 Chrome 调试端口 ----
    print("▶ 正在检测 Chrome 远程调试端口...")
    find_chrome_processes()

    ws_url = get_cdp_url_from_http()

    if not ws_url:
        print()
        print("  自动检测失败，可能原因：")
        print("  1. Chrome 没有以 --remote-debugging-port=9222 启动")
        print("  2. 端口被防火墙阻止")
        print("  3. 其他程序占用了 9222 端口")
        print()
        print("  解决方法：")
        print("  步骤 A：关闭所有 Chrome 窗口")
        print("  步骤 B：Win+R → 输入 cmd → 粘贴以下命令：")
        print('    "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe" --remote-debugging-port=9222')
        print()
        print("  或者如果你在用 agent-browser，先运行：")
        print("    agent-browser open https://example.com")
        print("    然后在另一个终端运行：")
        print("    agent-browser get cdp-url")
        print()
        ws_url = input("  手动输入 WebSocket URL: ").strip()

    if not ws_url:
        print("未提供 URL，退出。")
        return

    # ---- 连接 CDP ----
    print("\n▶ 正在连接 Chrome CDP...")
    client = CdpClient(ws_url)
    try:
        client.connect()

        # ---- 选择页面 ----
        url = input("\n请输入要分析的页面 URL (默认 https://www.baidu.com): ").strip()
