        print_separator("演示结束")
        print("  总结：")
        print("  • DOM 树包含所有 HTML 元素，包括隐藏的、装饰性的")
        print("  • Accessibility Tree 只保留可见、有语义的元素")
        print("  • Cursor-Interactive 检测能发现非标准交互元素")
        print("  • agent-browser 结合两者，给 AI 最精简的页面描述")
        print()

    finally:
        client.close()


